// PDF uses high-resolution slide canvases; Turkish glyphs use the browser font.
function canvasText(g,text,x,y,width,size,color='#17243b',bold=false,maxLines=3){
 g.fillStyle=color;g.font=`${bold?'700':'400'} ${size}px Arial, sans-serif`;g.textBaseline='top';
 const lines=[];for(const part of String(text||'').split('\n')){let line='';for(const word of part.split(/\s+/)){if(g.measureText(line+(line?' ':'')+word).width>width&&line){lines.push(line);line=word;}else line+=(line?' ':'')+word;}lines.push(line);}
 lines.slice(0,maxLines).forEach((line,i)=>{if(i===maxLines-1&&lines.length>maxLines)line+='…';g.fillText(line,x,y+i*size*1.22,width);});return Math.min(lines.length,maxLines)*size*1.22;
}
async function chartImage(w,width,height){let svg=visual(w).split('</svg>')[0]+'</svg>';if(w.kind!=='pie'){const correction=(height/270)/(width/640);svg=svg.replace(/<text([^>]*)>(.*?)<\/text>/g,(full,attrs,text)=>{const x=attrs.match(/\bx="([^"]+)"/)[1],y=attrs.match(/\by="([^"]+)"/)[1];attrs=attrs.replace(/font-size="([^"]+)"/,(_,size)=>'font-size="'+(Number(size)*550/height)+'"');return `<g transform="translate(${x} ${y}) scale(${correction} 1)"><text${attrs.replace(/\bx="[^"]+"/,'x="0"').replace(/\by="[^"]+"/,'y="0"')}>${text}</text></g>`;});}const blob=new Blob([svg.replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="540" style="font-family:Arial,sans-serif" ')],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);try{return await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Grafik PDF için çizilemedi.'));img.src=url;});}finally{URL.revokeObjectURL(url);}}
